<script>const drawingModal=document.getElementById('drawingModal'),registrationDetailModal=document.getElementById('registrationDetailModal'),registrationDetailFrame=document.getElementById('registrationDetailFrame');function openDrawingForm(data){document.getElementById('d_task').value=data.id;document.getElementById('d_customer').value=data.customer||'';document.getElementById('d_project').value=data.project||'';document.getElementById('d_part_number').value=data.part_number||'';document.getElementById('d_part_name').value=data.part_name||'';document.getElementById('d_revision').value=data.revision||'';document.getElementById('d_category').value=data.category||'';document.getElementById('d_date').value=new Date().toISOString().slice(0,10);document.getElementById('drawingModalTitle').textContent='Proses Drawing — '+(data.part_number||'');drawingModal.showModal()}function openRegistrationDetail(data){document.getElementById('registrationDetailTitle').textContent='Edit Registrasi '+(data.number||'');registrationDetailFrame.src=@json(route('document-control.index',absolute:false))+'?embedded=1&edit='+encodeURIComponent(data.id);registrationDetailModal.showModal()}function closeRegistrationDetail(){registrationDetailModal.close();registrationDetailFrame.src='';location.reload()}</script>
<script>document.querySelector('#registration-list .inbox-head>a')?.remove();window.addEventListener('message',event=>{if(event.origin!==location.origin)return;if(event.data?.type==='registration-detail-close'||event.data?.type==='registration-detail-saved')closeRegistrationDetail()});</script>
<script>const distributionConfirmModal=document.getElementById('distributionConfirmModal'),distributionConfirmNumber=document.getElementById('distributionConfirmNumber');let pendingDistributionForm=null;document.querySelectorAll('.distribution-complete-form').forEach(form=>form.addEventListener('submit',event=>{event.preventDefault();pendingDistributionForm=form;distributionConfirmNumber.textContent=form.dataset.registration||'-';distributionConfirmModal.showModal()}));document.getElementById('distributionCancelButton').addEventListener('click',()=>{pendingDistributionForm=null;distributionConfirmModal.close()});document.getElementById('distributionConfirmButton').addEventListener('click',()=>{if(!pendingDistributionForm)return;const form=pendingDistributionForm;pendingDistributionForm=null;distributionConfirmModal.close();form.submit()});distributionConfirmModal.addEventListener('cancel',()=>{pendingDistributionForm=null});</script>
<script>
const drawingTypeControl=document.querySelector('#drawingModal [name="drawing_type"]');
const drawingProcessForm=document.querySelector('#drawingModal form');
if(drawingProcessForm){
 const manualProjectInput=document.createElement('input');manualProjectInput.type='hidden';manualProjectInput.name='manual_project_id';manualProjectInput.id='d_manual_project';drawingProcessForm.appendChild(manualProjectInput);
 const completeInput=document.createElement('input');completeInput.type='hidden';completeInput.name='complete_distribution';completeInput.value='1';drawingProcessForm.appendChild(completeInput);
 const submitButton=drawingProcessForm.querySelector('.drawing-modal-foot button:not([type="button"])');if(submitButton)submitButton.textContent='Selesaikan Distribusi';
}
const drawingListButton=document.querySelector('a[href="#registration-list"]');
if(drawingListButton){drawingListButton.textContent='+ Registrasi Drawing';drawingListButton.href='#';drawingListButton.addEventListener('click',event=>{event.preventDefault();openManualDrawingForm()})}
function openManualDrawingForm(){
 drawingProcessForm.reset();document.getElementById('d_task').value='';document.getElementById('d_manual_project').value='';document.getElementById('d_date').value=new Date().toISOString().slice(0,10);
 ['d_customer','d_project','d_part_number','d_part_name'].forEach(id=>{const input=document.getElementById(id);input.readOnly=false;input.value=''});
 document.getElementById('d_revision').value='V0';document.getElementById('d_category').value='';document.getElementById('drawingModalTitle').textContent='Registrasi Drawing Tanpa A00';
 let manualInput=drawingProcessForm.querySelector('[name="create_manual_project"]');if(!manualInput){manualInput=document.createElement('input');manualInput.type='hidden';manualInput.name='create_manual_project';drawingProcessForm.appendChild(manualInput)}manualInput.value='1';
 const a00Input=drawingProcessForm.querySelector('[name="a00"]');if(a00Input)a00Input.value='tidak ada';drawingModal.showModal();
}
const originalOpenDrawingForm=openDrawingForm;
openDrawingForm=function(data){const manualInput=drawingProcessForm.querySelector('[name="create_manual_project"]');if(manualInput)manualInput.remove();document.getElementById('d_manual_project').value='';['d_project','d_part_number','d_part_name'].forEach(id=>document.getElementById(id).readOnly=true);const a00Input=drawingProcessForm.querySelector('[name="a00"]');if(a00Input)a00Input.value='ada';originalOpenDrawingForm(data)};
function openBreakdownRegistration(data){drawingProcessForm.reset();const manualInput=drawingProcessForm.querySelector('[name="create_manual_project"]');if(manualInput)manualInput.remove();document.getElementById('d_task').value='';document.getElementById('d_manual_project').value=data.project_id||'';document.getElementById('d_customer').value=data.customer||'';document.getElementById('d_project').value=data.project||'';document.getElementById('d_part_number').value=data.part_number||'';document.getElementById('d_part_name').value=data.part_name||'';document.getElementById('d_revision').value=data.revision||'V0';document.getElementById('d_category').value=data.category||'';document.getElementById('d_date').value=new Date().toISOString().slice(0,10);['d_project','d_part_number','d_part_name'].forEach(id=>document.getElementById(id).readOnly=true);const a00Input=drawingProcessForm.querySelector('[name="a00"]');if(a00Input)a00Input.value='tidak ada';document.getElementById('drawingModalTitle').textContent='Buat Registrasi Drawing — '+(data.part_number||'Project');drawingModal.showModal()}
if(drawingTypeControl){
 const select=document.createElement('select');select.name='drawing_type';
 ['Drawing Assy','Drawing Assy develop','Drawing Others','Drawing Sub, Assy','Drawing Sub, Others'].forEach(value=>{const option=document.createElement('option');option.value=value;option.textContent=value;option.selected=value==='Drawing Sub, Assy';select.appendChild(option)});
 drawingTypeControl.replaceWith(select);
}
const drawingCustomerControl=document.getElementById('d_customer');
if(drawingCustomerControl){
 drawingCustomerControl.readOnly=false;drawingCustomerControl.setAttribute('list','drawingCustomerOptions');drawingCustomerControl.setAttribute('autocomplete','off');
 const list=document.createElement('datalist');list.id='drawingCustomerOptions';
 @json($customerOptions).forEach(value=>{const option=document.createElement('option');option.value=value;list.appendChild(option)});
 drawingCustomerControl.after(list);
}
const drawingCategoryControl=document.getElementById('d_category');
if(drawingCategoryControl){
 const select=document.createElement('select');select.name='business_category';select.id='d_category';
 const placeholder=document.createElement('option');placeholder.value='';placeholder.textContent='Pilih kategori bisnis';select.appendChild(placeholder);
 const activeCategoryName=@json($activeBusinessCategory?->name);
 @json($businessCategoryOptions).forEach(category=>{const option=document.createElement('option');option.value=category.name;option.textContent=`${category.code} - ${category.name}`;option.selected=category.name===activeCategoryName;select.appendChild(option)});
 drawingCategoryControl.replaceWith(select);
}
</script>
<script>const activeDocumentControlTab=@json($tab);document.querySelectorAll('.inbox-search').forEach(form=>{const tabInput=document.createElement('input');tabInput.type='hidden';tabInput.name='tab';tabInput.value=activeDocumentControlTab;form.appendChild(tabInput)});</script>
@endsection
